import{_ as o,o as c,c as i,a5 as a}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Task — G2 Creator Upload (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g2-creator-upload/task.md","filePath":"mobile/features/g2-creator-upload/task.md"}'),l={name:"mobile/features/g2-creator-upload/task.md"};function t(d,e,r,n,s,h){return c(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="task-—-g2-creator-upload-mobile" tabindex="-1">Task — G2 Creator Upload (Mobile) <a class="header-anchor" href="#task-—-g2-creator-upload-mobile" aria-label="Permalink to &quot;Task — G2 Creator Upload (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a></p><h2 id="backend-business-service-—-đa-code-xong-2026-10-22-cho-team-confirm-policy" tabindex="-1">Backend (business-service) — ĐÃ CODE XONG (2026-10-22), chờ team confirm policy <a class="header-anchor" href="#backend-business-service-—-đa-code-xong-2026-10-22-cho-team-confirm-policy" aria-label="Permalink to &quot;Backend (business-service) — ĐÃ CODE XONG (2026-10-22), chờ team confirm policy&quot;">​</a></h2><ul><li>[x] Thêm <code>createPresignedUploadUrl(key, contentType, ttlSeconds)</code> vào <code>FileStorageService</code> + <code>S3FileStorageServiceImpl</code> (<code>PutObjectPresignRequest</code>, cùng pattern <code>createPresignedDownloadUrl</code>).</li><li>[x] Thêm field <code>taskId</code> (nullable) vào <code>MaterialDocument</code> + <code>MaterialResponse</code> DTO + wiring <code>toResponse()</code>.</li><li>[x] <code>POST /api/v1/workspaces/{workspaceId}/materials/upload-session</code> — role <code>CREATOR</code>, check assignee (<code>task.assigneeId == currentUser</code>) + status không phải FINISHED/CANCELLED, whitelist content-type (<code>video/mp4</code>, <code>video/quicktime</code>), sinh S3 key <code>video/materials/{workspaceId}/{taskId}/{epochMillis}-{uuid}.{ext}</code>, trả <code>uploadUrl</code>/<code>s3Key</code>/<code>expiresAt</code> (TTL 15 phút hard-code).</li><li>[x] <code>POST /api/v1/workspaces/{workspaceId}/materials/upload-session/confirm</code> — re-check quyền y hệt bước trên, idempotent theo <code>s3Key</code> (<code>findByS3Key</code>, trả record cũ nếu đã tồn tại), lưu <code>MaterialDocument</code> với <code>type=RAW</code>.</li><li>[x] Policy max file size — <strong>CHƯA CHỐT VỚI TEAM</strong>, tạm hard-code 1GB (<code>MAX_UPLOAD_FILE_SIZE_BYTES</code>) ở <code>MaterialServiceImpl</code>, lỗi <code>UPLOAD_FILE_TOO_LARGE</code> (400) nếu vượt — <strong>note hỏi team</strong>: số này đúng chưa, có cần khác nhau theo plan (G7) không.</li><li>[ ] HEAD-object verify trước khi lưu Material ở bước confirm — <strong>chưa làm</strong> (chấp nhận rủi ro nhỏ record &quot;ma&quot; như spec đã ghi, bỏ qua cho MVP).</li></ul><p><strong>Error codes mới thêm vào <code>ErrorCode.java</code>:</strong> <code>TASK_NOT_FOUND_FOR_UPLOAD</code> (404), <code>TASK_NOT_ASSIGNED</code> (403), <code>TASK_NOT_ACTIVE</code> (409), <code>INVALID_UPLOAD_CONTENT_TYPE</code> (400), <code>UPLOAD_FILE_TOO_LARGE</code> (400).</p><h2 id="mobile-—-dependencies" tabindex="-1">Mobile — dependencies <a class="header-anchor" href="#mobile-—-dependencies" aria-label="Permalink to &quot;Mobile — dependencies&quot;">​</a></h2><ul><li>[ ] <code>expo install expo-camera expo-image-picker</code> (chưa có trong <code>package.json</code>).</li><li>[ ] Xác nhận <code>expo-file-system</code> version hỗ trợ <code>createUploadTask</code> với progress callback.</li></ul><h2 id="mobile-—-screens-flow" tabindex="-1">Mobile — screens &amp; flow <a class="header-anchor" href="#mobile-—-screens-flow" aria-label="Permalink to &quot;Mobile — screens &amp; flow&quot;">​</a></h2><ul><li>[ ] Task List (assigned) — lọc <code>assigneeId=currentUser</code>, status chưa <code>FINISHED</code>/<code>CANCELLED</code> (dùng API Task tạm nếu G5 chưa xong, không thiết kế lại Task list ở đây).</li><li>[ ] Task Detail — thêm nút &quot;Quay video&quot; (<code>expo-camera</code>) / &quot;Chọn từ thư viện&quot; (<code>expo-image-picker</code>, <code>mediaTypes: Videos</code>).</li><li>[ ] Màn Upload: hiển thị tên file + dung lượng, nút &quot;Bắt đầu upload&quot;.</li><li>[ ] Gọi <code>upload-session</code> lấy <code>uploadUrl</code>+<code>s3Key</code> → <code>FileSystem.createUploadTask</code> PUT với progress bar.</li><li>[ ] PUT xong → gọi <code>upload-session/confirm</code>.</li><li>[ ] Màn &quot;Đã gắn vào Task&quot; sau khi confirm thành công.</li></ul><h2 id="mobile-—-resilience" tabindex="-1">Mobile — resilience <a class="header-anchor" href="#mobile-—-resilience" aria-label="Permalink to &quot;Mobile — resilience&quot;">​</a></h2><ul><li>[ ] Retry auto tối đa 3 lần khi lỗi network (không phải 4xx), backoff 2s/5s/10s; hết retry → nút &quot;Thử lại&quot; thủ công.</li><li>[ ] Giữ file local (không xoá cache) cho tới khi confirm thành công.</li><li>[ ] Xử lý lỗi 403 signature-expired từ PUT: gọi lại <code>upload-session</code> lấy key mới, PUT lại từ đầu.</li><li>[ ] Lưu <code>s3Key</code>+<code>taskId</code> vào local storage khi PUT xong nhưng chưa confirm — cho phép gọi lại confirm trực tiếp (không PUT lại) nếu app bị đóng giữa chừng.</li><li>[ ] Giới hạn Expo managed: upload chỉ chạy foreground — dừng khi app bị kill/minimize, resume khi mở lại (không background transfer thật).</li></ul><h2 id="chua-lam-out-of-scope-g2-xem-spec-muc-7" tabindex="-1">Chưa làm / out of scope G2 (xem spec mục 7) <a class="header-anchor" href="#chua-lam-out-of-scope-g2-xem-spec-muc-7" aria-label="Permalink to &quot;Chưa làm / out of scope G2 (xem spec mục 7)&quot;">​</a></h2><ul><li>[ ] Không làm: AI auto-edit raw footage, auto-caption, tự tạo Task mới sau upload, S3 Multipart Upload resumable thật, background upload khi app kill/minimize.</li></ul><h2 id="rui-ro-con-mo-xem-spec-muc-8" tabindex="-1">Rủi ro còn mở (xem spec mục 8) <a class="header-anchor" href="#rui-ro-con-mo-xem-spec-muc-8" aria-label="Permalink to &quot;Rủi ro còn mở (xem spec mục 8)&quot;">​</a></h2><ul><li>Giới hạn file size chưa chốt số cụ thể.</li><li>Field <code>taskId</code> mới trên <code>MaterialDocument</code> cần xác nhận với backend dev trước khi code (thay đổi schema).</li><li>Video compression: MVP không làm, chỉ giảm resolution record 720p nếu dung lượng gây vấn đề thực tế.</li></ul>',15)])])}const p=o(l,[["render",t]]);export{m as __pageData,p as default};
